  "SplatFields": { abstractEn: "Implicit neural field regularization on splat features for sparse-view 3D/4D reconstruction [Abstract pending — contribution details to be added]", abstractCn: "隐式神经场正则化溅射特征用于稀疏视图3D/4D重建。 [摘要待补充——贡献详情待添加]" },
  "SuperSplat": { abstractEn: "Super-resolution guided Gaussian densification for detail enhancement in sparse-view settings [Abstract pending — contribution details to be added]", abstractCn: "Super-resolution guided Gaussian 致密化 用于 detail enhancement in 稀疏视图 settings。 [摘要待补充——贡献详情待添加]" },
  "SwagGS": { abstractEn: "Splatting with adaptive Gaussians: adaptive covariance optimization replacing hand-tuned schedules [Abstract pending — contribution details to be added]", abstractCn: "溅射 结合 自适应 Gaussians: 自适应 covariance 优化 替代 hand-tuned schedules。 [摘要待补充——贡献详情待添加]" },
  "WildGaussians": { abstractEn: "Joint pose + 3DGS optimization from internet photos [Abstract pending — contribution details to be added]", abstractCn: "联合 pose + 3DGS 优化 从 internet photos。 [摘要待补充——贡献详情待添加]" },
  "2D-SuGaR": { abstractEn: "2D-SuGaR extends 2D Gaussian Splatting by incorporating monocular depth and normal priors from pretrained networks to improve surface reconstruction quality. The depth and normal priors serve as additional regularization signals during 2DGS optimization, guiding the placement and orientation of surface-aligned Gaussian disks. This hybrid approach combines the geometric advantages of 2DGS with rich geometric supervision from foundation models. Results demonstrate improved mesh quality and rendering fidelity over vanilla 2DGS, particularly in textureless or geometrically ambiguous regions.", abstractCn: "2D-SuGaR通过引入预训练网络的深度和法线先验扩展了2D高斯溅射，提升表面重建质量。深度和法线先验在2DGS优化过程中作为额外的正则化信号，指导表面对齐高斯圆盘的位置和朝向。这种混合方法结合了2DGS的几何优势和基础模型提供的丰富几何监督。结果表明，相比原始2DGS，网格质量和渲染保真度均有提升，尤其在无纹理或几何模糊区域。" },
  "3DSS": { abstractEn: "3D Surface Splatting presents the first differentiable surface splatting renderer designed for physically based rendering (PBR) inverse rendering. It introduces coverage-based compositing derived from EWA splatting theory, properly handling surface visibility and antialiasing for PBR material models. The differentiable pipeline supports gradient-based optimization of material properties including roughness, metallic, and specular reflectance. Experiments demonstrate high-quality PBR material recovery on standard benchmarks, establishing surface splatting as a viable alternative to volume rendering for inverse graphics.", abstractCn: "3D表面溅射提出了首个为基于物理的渲染（PBR）逆渲染设计的可微表面溅射渲染器。它引入了基于EWA溅射理论的覆盖率合成，正确处理PBR材质模型的表面可见性和抗锯齿。可微管线支持基于梯度的材质属性优化，包括粗糙度、金属度和镜面反射率。实验在标准基准上展示了高质量的PBR材质恢复，确立了表面溅射作为逆图形学中体渲染替代方案的可行性。" },
  "AmbiSuR": { abstractEn: "Photometric ambiguity disambiguation for accurate GS surface reconstruction. [摘要待补充——贡献详情待添加]", abstractCn: "Photometric ambiguity disambiguation 用于 accurate GS 表面重建. [摘要待补充——贡献详情待添加]" },
  "CLEAR-NeRF": { abstractEn: "CLEAR-NeRF achieves accurate 3D reconstruction in unbounded scenes via collinearity and local-region enhancement.", abstractCn: "CLEAR-NeRF通过共线性和局部区域增强实现无界场景精确3D重建。" },
  "DinoComplete": { abstractEn: "DinoComplete performs 3D shape completion using DINOv2-distilled semantic priors combined with a state space model.", abstractCn: "DinoComplete利用DINOv2蒸馏语义先导配合状态空间模型实现3D形状补全。" },
