  "TransmissiveGS": { abstractEn: "TransmissiveGS introduces residual-guided disentangled Gaussian Splatting for transmissive scene reconstruction, separating reflection and transmission components to handle challenging see-through surfaces like glass and water.", abstractCn: "TransmissiveGS提出残差引导解耦3DGS框架，分离反射与透射分量，有效重建玻璃、水面等透射场景。" },
  "TRiGS": { abstractEn: "Tri-plane augmented Gaussian Splatting: tri-plane features + Gaussian geometry for hybrid representation [Abstract pending — contribution details to be added]", abstractCn: "Tri-plane augmented Gaussian 溅射: tri-plane features + Gaussian geometry 用于 混合 representation。 [摘要待补充——贡献详情待添加]" },
  "View-Dependent Splatting": { abstractEn: "View-Dependent Splatting replaces fixed covariance with learned view-dependent splatting kernels, the first fundamental rethink of the 3DGS rendering primitive. SIGGRAPH 2026.", abstractCn: "View-Dependent Splatting用学习型视角相关Splatting核替代固定协方差，是对3DGS渲染基元首次根本性重新设计。SIGGRAPH 2026。" },
