  "GS-Playground": { abstractEn: "Batch 3DGS + parallel physics at 10^4 FPS for robot learning [Abstract pending — contribution details to be added]", abstractCn: "Batch 3DGS + parallel 物理 at 10^4 FPS 用于 robot learning。 [摘要待补充——贡献详情待添加]" },
  "GS-Surrogate": { abstractEn: "Deformable GS surrogate for ensemble simulation exploration [Abstract pending — contribution details to be added]", abstractCn: "Deformable GS surrogate 用于 ensemble 仿真 exploration。 [摘要待补充——贡献详情待添加]" },
  "GS-World": { abstractEn: "GS-World unifies world model generative simulation with Engine-driven Sim2Real VLA, using 3DGS as a differentiable and physically consistent simulation engine for robot skill learning.", abstractCn: "GS-World统一世界模型生成式仿真与引擎驱动Sim2Real VLA，将3DGS作为可微且物理一致的仿真引擎用于机器人技能学习。" },
  "GSDrive": { abstractEn: "GSDrive reinforces autonomous driving policies by providing high-fidelity 3D Gaussian Splatting environments for reinforcement learning training. The method reconstructs real-world driving scenes as differentiable 3DGS environments where RL agents can interact with photo-realistic surroundings. A sensor simulation module renders LiDAR point clouds and camera images from the 3DGS representation, bridging the gap between simulation and real-world deployment. Experiments on the CARLA benchmark show that policies trained in 3DGS environments transfer more effectively to real driving scenarios than those trained in conventional simulators.", abstractCn: "GSDrive通过提供高保真3D高斯泼溅环境进行强化学习训练，以增强自动驾驶策略。该方法将真实世界驾驶场景重建为可微3DGS环境，RL智能体可在其中与照片级真实感环境交互。传感器仿真模块从3DGS表示渲染LiDAR点云和相机图像，缩小仿真与真实部署之间的差距。在CARLA基准上的实验表明，在3DGS环境中训练的策略比在传统仿真器中训练的策略能更有效地迁移到真实驾驶场景。" },
  "GSMem": { abstractEn: "3DGS as persistent spatial memory for zero-shot embodied exploration and reasoning [Abstract pending — contribution details to be added]", abstractCn: "3DGS as persistent spatial 内存 用于 零样本 embodied exploration and reasoning。 [摘要待补充——贡献详情待添加]" },
  "LeGS": { abstractEn: "RL-learnable density control replacing heuristic clone/split/prune [Abstract pending — contribution details to be added]", abstractCn: "RL-可学习 density control 替代 heuristic clone/split/prune。 [摘要待补充——贡献详情待添加]" },
